/**
 * @description A window overlaid on the primary content, rendering content in a layer above the page.
 */
import { Dialog as DialogPrimitive } from "radix-ui";
import { Cross2Icon } from "@radix-ui/react-icons";

import { cn } from "@/utils/class-names";
import { Button } from "@/components/ui/Button";

function Dialog({
  ...props
}: React.ComponentProps<typeof DialogPrimitive.Root>) {
  return <DialogPrimitive.Root data-slot="dialog" {...props} />;
}

function DialogTrigger({
  ...props
}: React.ComponentProps<typeof DialogPrimitive.Trigger>) {
  return <DialogPrimitive.Trigger data-slot="dialog-trigger" {...props} />;
}

function DialogPortal({
  ...props
}: React.ComponentProps<typeof DialogPrimitive.Portal>) {
  return <DialogPrimitive.Portal data-slot="dialog-portal" {...props} />;
}

function DialogClose({
  ...props
}: React.ComponentProps<typeof DialogPrimitive.Close>) {
  return <DialogPrimitive.Close data-slot="dialog-close" {...props} />;
}

function DialogOverlay({
  className,
  ...props
}: React.ComponentProps<typeof DialogPrimitive.Overlay>) {
  return (
    <DialogPrimitive.Overlay
      data-slot="dialog-overlay"
      className={cn(
        "aura-overlay z-50",
        className
      )}
      {...props}
    />
  );
}

function DialogContent({
  className,
  children,
  ...props
}: React.ComponentProps<typeof DialogPrimitive.Content>) {
  return (
    <DialogPortal data-slot="dialog-portal">
      <DialogOverlay />
      <DialogPrimitive.Content
        data-slot="dialog-content"
        className={cn(
          "smash fixed left-1/2 top-1/2 max-h-[85vh] w-[90vw] -translate-x-1/2 -translate-y-1/2 bg-gray-1 p-2 rounded-md z-50 data-[state=open]:animate-content-show border border-gray-a6",
          className
        )}
        {...props}
      >
        {children}
        <DialogPrimitive.Close asChild>
          <Button mode="link" className="absolute top-0.5 right-0.5">
            <Cross2Icon />
          </Button>
        </DialogPrimitive.Close>
      </DialogPrimitive.Content>
    </DialogPortal>
  );
}

function DialogHeader({ ...props }: React.ComponentProps<"div">) {
  return <div data-slot="dialog-header" {...props} />;
}

function DialogFooter({
  className,
  ...props
}: React.ComponentProps<"div">) {
  return (
    <div
      data-slot="dialog-footer"
      className={cn("flex justify-end gap-1", className)}
      {...props}
    />
  );
}

function DialogTitle({
  ...props
}: React.ComponentProps<typeof DialogPrimitive.Title>) {
  return <DialogPrimitive.Title data-slot="dialog-title" {...props} />;
}

function DialogDescription({
  ...props
}: React.ComponentProps<typeof DialogPrimitive.Description>) {
  return (
    <DialogPrimitive.Description data-slot="dialog-description" {...props} />
  );
}

export {
  Dialog,
  DialogClose,
  DialogContent,
  DialogDescription,
  DialogFooter,
  DialogHeader,
  DialogOverlay,
  DialogPortal,
  DialogTitle,
  DialogTrigger,
};

@theme animatons {
    --animate-overlay-show: overlayShow 150ms cubic-bezier(0.16, 1, 0.3, 1);
    --animate-content-show: contentShow 150ms cubic-bezier(0.16, 1, 0.3, 1);
  }

  @layer components {
    @keyframes overlayShow {
      from {
        opacity: 0;
      }
      to {
        opacity: 1;
      }
    }

    @keyframes contentShow {
      from {
        opacity: 0;
        transform: scale(0.96);
      }
      to {
        opacity: 1;
        transform: scale(1);
      }
    }
  }

@media (prefers-reduced-motion: reduce) {
  @layer components {
    [data-slot="dialog-overlay"],
    [data-slot="dialog-content"],
    [data-slot="alert-dialog-overlay"],
    [data-slot="alert-dialog-content"] {
      animation: none;
    }
  }
}

/*
 * Shared modal scrim for every Aura overlay.
 *
 * --aura-overlay is rgb(16 11 33 / 0.08): dark gray-1 (#100B21) at 8%.
 * The same value is set in light and dark in registry globals. It is not
 * var(--gray-1), because gray-1 is near-white in light mode.
 * Declared here as well so the tint ships with this file.
 * backdrop-filter matches backdrop-blur-xs (--blur-xs is 4px).
 * Enter fade is opacity 0 to 1, 150ms, cubic-bezier(0.16, 1, 0.3, 1).
 *
 * `@theme animatons` (the typo) still registered --animate-* tokens. Tailwind v4
 * ignores unknown @theme words; it does not drop the custom properties.
 * sheet.css and alert-dialog.css use `@theme animations`.
 */

:root {
  --aura-overlay: rgb(16 11 33 / 0.08);
}

@keyframes aura-overlay-show {
  from {
    opacity: 0;
  }
  to {
    opacity: 1;
  }
}

@keyframes aura-overlay-hide {
  from {
    opacity: 1;
  }
  to {
    opacity: 0;
  }
}

.aura-overlay {
  position: fixed;
  inset: 0;
  background-color: var(--aura-overlay);
  -webkit-backdrop-filter: blur(4px);
  backdrop-filter: blur(4px);
}

.aura-overlay[data-state="open"] {
  animation: aura-overlay-show 150ms cubic-bezier(0.16, 1, 0.3, 1);
}

/*
 * vaul injects an unlayered 500ms fadeIn/fadeOut on [data-vaul-overlay].
 * !important keeps the 150ms fade when this file is imported inside a layer.
 */
.aura-overlay[data-vaul-overlay][data-vaul-snap-points][data-state="open"] {
  animation: aura-overlay-show 150ms cubic-bezier(0.16, 1, 0.3, 1) !important;
}

.aura-overlay[data-vaul-overlay][data-vaul-snap-points][data-state="closed"] {
  animation: aura-overlay-hide 150ms cubic-bezier(0.16, 1, 0.3, 1) !important;
}

.aura-overlay[data-starting-style],
.aura-overlay[data-ending-style] {
  opacity: 0;
}

@media (prefers-reduced-motion: no-preference) {
  .aura-overlay:is([data-open], [data-closed], [data-starting-style], [data-ending-style]) {
    transition: opacity 150ms cubic-bezier(0.16, 1, 0.3, 1);
  }
}

@media (prefers-reduced-motion: reduce) {
  .aura-overlay,
  .aura-overlay[data-state="open"],
  .aura-overlay[data-state="closed"],
  .aura-overlay[data-starting-style],
  .aura-overlay[data-ending-style],
  .aura-overlay[data-vaul-overlay][data-vaul-snap-points][data-state="open"],
  .aura-overlay[data-vaul-overlay][data-vaul-snap-points][data-state="closed"] {
    animation: none !important;
    transition: none;
    opacity: 1;
  }
}
